CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, company_name TEXT, role TEXT DEFAULT 'client', is_active INTEGER DEFAULT 1, created_at TEXT DEFAULT (datetime('now')), session_token TEXT, session_expires TEXT);
CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY, user_id INTEGER, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT, service_type TEXT, package_name TEXT, source_url TEXT, website TEXT, budget TEXT, message TEXT, details TEXT, email_abandoned_1_sent INTEGER DEFAULT 0, email_abandoned_2_sent INTEGER DEFAULT 0, status TEXT DEFAULT 'new', current_step INTEGER DEFAULT 1, created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL, status TEXT DEFAULT 'pending', progress INTEGER DEFAULT 0, drive_link TEXT, next_milestone TEXT, next_milestone_date TEXT, budget TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS milestones (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, title TEXT NOT NULL, description TEXT, due_date TEXT, status TEXT DEFAULT 'pending', feedback TEXT, order_index INTEGER DEFAULT 0, created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, admin_id INTEGER, project_id INTEGER, content TEXT NOT NULL, sender_type TEXT NOT NULL, is_read INTEGER DEFAULT 0, created_at TEXT DEFAULT (datetime('now')), notification_sent INTEGER DEFAULT 0, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, name TEXT NOT NULL, file_path TEXT NOT NULL, type TEXT NOT NULL, subtype TEXT DEFAULT 'other', created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS auth_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL, token TEXT NOT NULL, expires_at TEXT NOT NULL, used INTEGER DEFAULT 0, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS performance_metrics (id INTEGER PRIMARY KEY AUTOINCREMENT, metric_name TEXT NOT NULL, metric_value REAL NOT NULL, page_url TEXT NOT NULL, user_agent TEXT, device_type TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS logs (id INTEGER PRIMARY KEY AUTOINCREMENT, level TEXT NOT NULL, message TEXT NOT NULL, context TEXT, created_at TEXT DEFAULT (datetime('now')));